            }
        }
        LocalDate today = sheets.today(sheetId);
        BigDecimal dueTotal = !any && rates.pct(sheetId, person.gradeOn(today), today) == null ? null
                : settings.capped(sheetId, total);
        return new Taken(bound, dueTotal, today);
    }

    /** The date the statement is taken as of; null when none was given. */
    private static LocalDate asOfDate(StatementRequest request) throws InvalidSheetRequestException {
        String text = request.asOf();
        if (text == null || text.isBlank()) return null;
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + text);
        }
    }

    private record Taken(Map<Long, BigDecimal> bound, BigDecimal dueTotal, LocalDate date) {
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A statement taken for a person: their due-total then (null when n/a) and how many of their
 *  claims counted, by whom, and the date it was taken as of (null: taken now). */
public record Statement(BigDecimal dueTotal, int claims, String user, LocalDate asOf) {

    public Statement(BigDecimal dueTotal, int claims, String user) {
        this(dueTotal, claims, user, null);
    }
}
# Take a person's statement: record their due-total and bind their counting claims to their figures.
validate:
  class: net.officefloor.hq.app.person.ValidateStatement
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: take
take:
  class: net.officefloor.hq.app.person.TakeStatement
  govern: [ transaction ]
  next: record
# Audit only once the statement is saved.
record:
  class: net.officefloor.hq.app.person.RecordStatement
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
-- A person's statements: how many have been taken, and the last one's due-total (null when it was
-- n/a, or when none has been taken) and date (the sheet's today when it was taken).
ALTER TABLE person ADD COLUMN statement_count INT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total DECIMAL(14,2);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim that counted at its person's last statement is bound (`stated`) to the figure it had
-- then (`stated_due`, null when that was n/a): it shows and totals that figure, whatever later
-- rates or grades would make it, until the next statement rebinds or unbinds it. A settled
-- claim's fixed `due` still comes first.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14,2);
-- Every statement taken for a person, numbered from 1 in the order taken (`seq`), with its
-- due-total (null when n/a) and date: so cancelling the last one can show the one before it.
-- The person's statement_count, stated_total and statement_date stay the last one's.
CREATE TABLE person_statement (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL,
    person_id   BIGINT       NOT NULL REFERENCES person (id),
    seq         INT          NOT NULL,
    stated_total DECIMAL(14,2),
    statement_date DATE      NOT NULL
);
CREATE INDEX person_statement_person ON person_statement (person_id, seq);
-- A statement taken before this was kept is known only as the last one.
INSERT INTO person_statement (sheet_id, person_id, seq, stated_total, statement_date)
    SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person
    WHERE statement_count > 0 AND statement_date IS NOT NULL;

